"use client"

import * as React from "react"
import { CalendarDays } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Popover, PopoverTrigger, PopoverContent } from "@/components/ui/popover"
import { Calendar, type DateRange } from "@/components/wunderui/calendar"
import { cn } from "@/lib/utils"

function formatDate(date?: Date) {
  if (!date) return undefined
  return date.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })
}

function formatRange(range?: DateRange) {
  if (!range?.from) return undefined
  return range.to ? `${formatDate(range.from)} – ${formatDate(range.to)}` : formatDate(range.from)
}

function addMonths(date: Date, n: number) {
  return new Date(date.getFullYear(), date.getMonth() + n, 1)
}

type DatePreset = { label: string; range: () => DateRange }

/** The quick ranges of the Figma Date Picker · Type=presets sidebar. */
const DEFAULT_PRESETS: DatePreset[] = [
  { label: "Today", range: () => ({ from: new Date(), to: new Date() }) },
  { label: "Last 7 days", range: () => ({ from: daysAgo(6), to: new Date() }) },
  { label: "Last 30 days", range: () => ({ from: daysAgo(29), to: new Date() }) },
  { label: "Last 3 months", range: () => ({ from: addMonths(new Date(), -3), to: new Date() }) },
  { label: "Last 12 months", range: () => ({ from: addMonths(new Date(), -12), to: new Date() }) },
  { label: "Month to date", range: () => ({ from: new Date(new Date().getFullYear(), new Date().getMonth(), 1), to: new Date() }) },
  { label: "Year to date", range: () => ({ from: new Date(new Date().getFullYear(), 0, 1), to: new Date() }) },
]

function daysAgo(n: number) {
  const d = new Date()
  d.setDate(d.getDate() - n)
  return d
}

type DatePickerSingleProps = {
  mode?: "single"
  value?: Date
  defaultValue?: Date
  onValueChange?: (date: Date | undefined) => void
}

type DatePickerRangeProps = {
  mode: "range"
  value?: DateRange
  defaultValue?: DateRange
  onValueChange?: (range: DateRange | undefined) => void
  /** Quick-select sidebar (Figma: Type=presets). `true` uses the built-in presets. */
  presets?: boolean | DatePreset[]
  /** Months shown side by side. Defaults to 2 for range mode. */
  numberOfMonths?: 1 | 2
}

type DatePickerProps = (DatePickerSingleProps | DatePickerRangeProps) & {
  placeholder?: string
  className?: string
}

/**
 * DatePicker — mirrors the Figma Date Picker set: Type=single (one month),
 * Type=range (two months, start/end), Type=presets (range + quick-select sidebar).
 */
function DatePicker(props: DatePickerProps) {
  const { placeholder, className } = props
  const isRange = props.mode === "range"
  const [open, setOpen] = React.useState(false)
  const [uncontrolled, setUncontrolled] = React.useState<Date | DateRange | undefined>(props.defaultValue)
  const isControlled = props.value !== undefined
  const selected = isControlled ? props.value : uncontrolled
  const [draft, setDraft] = React.useState<Date | DateRange | undefined>(selected)
  const [month, setMonth] = React.useState<Date>(() => {
    const d = isRange ? (selected as DateRange | undefined)?.from : (selected as Date | undefined)
    return addMonths(d ?? new Date(), 0)
  })

  const presets = isRange ? (props.presets === true ? DEFAULT_PRESETS : props.presets || null) : null
  const months = isRange ? (props.numberOfMonths ?? 2) : 1

  function handleOpenChange(next: boolean) {
    if (next) setDraft(selected)
    setOpen(next)
  }

  function apply() {
    if (!isControlled) setUncontrolled(draft)
    if (isRange) (props as DatePickerRangeProps).onValueChange?.(draft as DateRange | undefined)
    else (props as DatePickerSingleProps).onValueChange?.(draft as Date | undefined)
    setOpen(false)
  }

  const display = isRange ? formatRange(selected as DateRange | undefined) : formatDate(selected as Date | undefined)
  const draftRange = draft as DateRange | undefined

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger render={<Button variant="plain" className={cn(isRange ? "w-72" : "w-56", "justify-start font-normal", className)} />}>
        <CalendarDays className="size-4" />
        {display ?? <span className="text-text-tertiary">{placeholder ?? (isRange ? "Pick a date range" : "Pick a date")}</span>}
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0">
        <div className="flex">
          {presets && (
            <div className="flex w-40 flex-col gap-0.5 border-r border-border p-3">
              {presets.map((p) => {
                const r = p.range()
                const active = draftRange?.from?.toDateString() === r.from?.toDateString() && draftRange?.to?.toDateString() === r.to?.toDateString()
                return (
                  <button key={p.label} type="button" onClick={() => (setDraft(r), setMonth(addMonths(r.from ?? new Date(), 0)))} className={cn("rounded-lg px-3 py-2 text-left text-xs font-medium transition-colors", active ? "bg-subtle font-semibold text-foreground" : "text-text-secondary hover:bg-subtle hover:text-foreground")}>
                    {p.label}
                  </button>
                )
              })}
            </div>
          )}
          <div className="flex gap-6 p-3">
            {Array.from({ length: months }).map((_, i) =>
              isRange ? (
                <Calendar key={i} mode="range" selected={draftRange} onSelect={setDraft} month={addMonths(month, i)} onMonthChange={(m) => setMonth(addMonths(m, -i))} />
              ) : (
                <Calendar key={i} mode="single" selected={draft as Date | undefined} onSelect={setDraft} month={month} onMonthChange={setMonth} />
              )
            )}
          </div>
        </div>
        <div className="flex justify-end gap-2 border-t border-border p-3">
          <Button variant="plain" size="sm" onClick={() => setOpen(false)}>
            Cancel
          </Button>
          <Button variant="primary" size="sm" onClick={apply}>
            Apply
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

export { DatePicker, DEFAULT_PRESETS as datePickerPresets }
export type { DatePickerProps, DatePreset }

"use client"

import * as React from "react"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { IconButton } from "@/components/ui/icon-button"
import { cn } from "@/lib/utils"

const WEEKDAY_LABELS = ["M", "T", "W", "T", "F", "S", "S"]

function isSameDay(a?: Date, b?: Date) {
  return !!a && !!b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
}

function startOfDay(d: Date) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate())
}

function getMonthGrid(month: Date) {
  const year = month.getFullYear()
  const m = month.getMonth()
  const firstOfMonth = new Date(year, m, 1)
  const mondayOffset = (firstOfMonth.getDay() + 6) % 7
  const gridStart = new Date(year, m, 1 - mondayOffset)
  return Array.from({ length: 42 }, (_, i) => {
    const d = new Date(gridStart)
    d.setDate(gridStart.getDate() + i)
    return d
  })
}

type DateRange = { from?: Date; to?: Date }

type CalendarSingleProps = {
  mode?: "single"
  selected?: Date
  onSelect?: (date: Date) => void
}

type CalendarRangeProps = {
  mode: "range"
  selected?: DateRange
  onSelect?: (range: DateRange) => void
}

type CalendarProps = (CalendarSingleProps | CalendarRangeProps) & {
  month?: Date
  defaultMonth?: Date
  onMonthChange?: (month: Date) => void
  className?: string
}

function Calendar({ mode = "single", selected, onSelect, month, defaultMonth, onMonthChange, className }: CalendarProps) {
  const initialSelected: Date | undefined = mode === "range" ? (selected as DateRange | undefined)?.from : (selected as Date | undefined)
  const [uncontrolledMonth, setUncontrolledMonth] = React.useState<Date>(
    () => defaultMonth ?? initialSelected ?? new Date()
  )
  const visibleMonth = month ?? uncontrolledMonth

  function changeMonth(next: Date) {
    if (!month) setUncontrolledMonth(next)
    onMonthChange?.(next)
  }

  const days = React.useMemo(() => getMonthGrid(visibleMonth), [visibleMonth])
  const today = React.useMemo(() => startOfDay(new Date()), [])

  function handleDayClick(day: Date) {
    if (mode === "range") {
      const range = (selected as DateRange | undefined) ?? {}
      const onRangeSelect = onSelect as CalendarRangeProps["onSelect"]
      if (!range.from || (range.from && range.to)) {
        onRangeSelect?.({ from: day, to: undefined })
      } else if (day < range.from) {
        onRangeSelect?.({ from: day, to: range.from })
      } else {
        onRangeSelect?.({ from: range.from, to: day })
      }
    } else {
      ;(onSelect as CalendarSingleProps["onSelect"])?.(day)
    }
  }

  function dayState(day: Date) {
    if (mode === "range") {
      const range = selected as DateRange | undefined
      const isStart = isSameDay(day, range?.from)
      const isEnd = isSameDay(day, range?.to)
      const inRange = !!range?.from && !!range?.to && day > range.from && day < range.to
      return { selected: isStart || isEnd, inRange, rangeStart: isStart, rangeEnd: isEnd }
    }
    return { selected: isSameDay(day, selected as Date | undefined), inRange: false, rangeStart: false, rangeEnd: false }
  }

  return (
    <div data-slot="calendar" className={cn("w-fit", className)}>
      <div className="mb-3 flex items-center justify-between">
        <IconButton
          type="button"
          variant="plain"
          size="sm"
          aria-label="Previous month"
          onClick={() => changeMonth(new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() - 1, 1))}
        >
          <ChevronLeft className="size-4" />
        </IconButton>
        <p className="text-sm font-semibold text-foreground">
          {visibleMonth.toLocaleDateString(undefined, { month: "long", year: "numeric" })}
        </p>
        <IconButton
          type="button"
          variant="plain"
          size="sm"
          aria-label="Next month"
          onClick={() => changeMonth(new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + 1, 1))}
        >
          <ChevronRight className="size-4" />
        </IconButton>
      </div>
      <div className="grid grid-cols-7 gap-y-1">
        {WEEKDAY_LABELS.map((label, i) => (
          <div key={i} className="flex h-8 items-center justify-center text-xs font-medium text-text-tertiary">
            {label}
          </div>
        ))}
        {days.map((day, i) => {
          const outside = day.getMonth() !== visibleMonth.getMonth()
          const { selected: isSelected, inRange, rangeStart, rangeEnd } = dayState(day)
          const isToday = isSameDay(day, today)
          return (
            <div key={i} className={cn("flex h-9 items-center justify-center", inRange && "bg-accent", rangeStart && "rounded-l-full", rangeEnd && "rounded-r-full")}>
              <button
                type="button"
                onClick={() => handleDayClick(day)}
                className={cn(
                  "flex size-8 items-center justify-center rounded-full text-sm transition-colors hover:bg-muted",
                  outside && "text-text-tertiary",
                  !outside && !isSelected && "text-foreground",
                  isToday && !isSelected && "font-semibold text-text-link",
                  isSelected && "bg-primary text-primary-foreground hover:bg-primary/90"
                )}
              >
                {day.getDate()}
              </button>
            </div>
          )
        })}
      </div>
    </div>
  )
}

export { Calendar }
export type { CalendarProps, DateRange }

import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

const iconButtonVariants = cva(
  "group/icon-button inline-flex shrink-0 items-center justify-center border border-transparent transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:translate-y-px disabled:pointer-events-none disabled:opacity-40 focus-visible:border-ring [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-muted",
        primary: "border-primary bg-primary text-primary-foreground hover:bg-primary/90",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:bg-brand-primary/90",
        gradient:
          "border-primary bg-gradient-to-b from-[#6f74f5] to-primary text-primary-foreground shadow-[inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:brightness-105",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-white",
        light: "bg-(--light-600) text-(--light-900) hover:bg-(--light-600)/90",
        outline: "bg-card border-primary text-foreground hover:bg-primary/5",
        // Figma Type=ghost / destructive (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-muted",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:bg-destructive/90",
      },
      shape: {
        rounded: "rounded-md",
        circle: "rounded-full",
      },
      size: {
        sm: "size-8 [&_svg]:size-4",
        md: "size-9 [&_svg]:size-[18px]",
        lg: "size-10 [&_svg]:size-5",
        xl: "size-11 [&_svg]:size-[22px]",
        "2xl": "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

function IconButton({
  className,
  variant,
  shape,
  size,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof iconButtonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, shape, size, className }))}
      {...props}
    />
  )
}

export { IconButton, iconButtonVariants }

"use client"

import * as React from "react"
import { Popover as PopoverPrimitive } from "@base-ui/react/popover"
import { cn } from "cn"

function Popover({ ...props }: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger({ ...props }: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverContent({
  className,
  sideOffset = 8,
  side,
  align,
  anchor,
  ...props
}: PopoverPrimitive.Popup.Props & Pick<PopoverPrimitive.Positioner.Props, "sideOffset" | "side" | "align" | "anchor">) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Positioner className="isolate z-50 outline-none" sideOffset={sideOffset} side={side} align={align} anchor={anchor}>
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          className={cn(
            "z-50 rounded-lg border border-border bg-popover [--surface:var(--popover)] p-3 text-popover-foreground shadow-lg outline-none",
            "data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-open:duration-base data-open:ease-overshoot data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-99 data-closed:duration-fast data-closed:ease-exit",
            className
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  )
}

/** Closes the popover it sits in — render it as an icon button for an ×, or around Cancel/Apply. */
function PopoverClose({ ...props }: PopoverPrimitive.Close.Props) {
  return <PopoverPrimitive.Close data-slot="popover-close" {...props} />
}

export { Popover, PopoverTrigger, PopoverContent, PopoverClose }

import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

// --primary/--brand-primary is the indigo brand color; its text uses
// --primary-foreground/--brand-primary-foreground (white), which is AA-safe
// on indigo. gradient tracks the same primary token (light tint -> primary),
// so its text reuses primary-foreground too. outline keeps a fixed white
// background independent of the primary token, so its text stays a fixed
// dark color (#25272a) rather than tracking primary-foreground, which is
// white and would fail contrast on that fixed white background.
// See /scripts/contrast-audit.mjs.
//
// Hover on the filled variants darkens with brightness-95 instead of the
// former bg-*/90. An alpha fill composites against whatever is behind the
// button, so on the white page it made the fill LIGHTER: white label on
// primary measured 4.99:1 at rest but only 4.17:1 while hovered, and
// destructive 5.04 -> 4.44 -- both under AA 4.5. brightness-95 darkens in
// both themes and keeps every filled variant at 4.85:1 (primary, brand) and
// 4.91:1 (destructive). Measured values are for the label, white or near
// white, against the fill; contrast-audit.mjs reads flat background colors
// only, so neither the hover alpha nor the gradient below was covered by it.
//
// The gradient top stop was #6f74f5, which put the top edge of the button at
// 3.82:1 -- the gradient, not the token, was the failure. #5a5ef4 keeps a
// visible sheen (4.84:1 top, 4.99:1 bottom) and the inset white highlight
// carries the rest of the raised look. Its hover brightened (brightness-105,
// 3.52:1); it now darkens like the other filled variants (4.71:1 top).
const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center gap-2 border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-40 focus-visible:border-ring [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-muted",
        primary: "border-primary bg-primary text-primary-foreground hover:brightness-95",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:brightness-95",
        gradient:
          "border-primary bg-gradient-to-b from-[#5a5ef4] to-primary text-primary-foreground shadow-[inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:brightness-95",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-white",
        light: "bg-white text-primary hover:bg-(--light-200)",
        // Figma Type=blue_outline: indigo rim, link-coloured label, indigo tint on hover.
        outline: "bg-card border-primary text-text-link hover:bg-tint-indigo hover:text-tint-text-indigo",
        // Figma Type=ghost / destructive / link (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-muted",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:brightness-95",
        link: "bg-transparent px-0! text-text-link shadow-none underline-offset-4 hover:underline",
      },
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
      size: {
        sm: "h-9 px-3.5 text-sm has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3",
        md: "h-10 px-4 text-sm has-data-[icon=inline-end]:pr-3.5 has-data-[icon=inline-start]:pl-3.5",
        lg: "h-11 px-[18px] text-sm has-data-[icon=inline-end]:pr-4 has-data-[icon=inline-start]:pl-4",
        xl: "h-12 px-5 text-base has-data-[icon=inline-end]:pr-4.5 has-data-[icon=inline-start]:pl-4.5",
        "2xl": "h-14 px-6 text-lg has-data-[icon=inline-end]:pr-5 has-data-[icon=inline-start]:pl-5",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

function Button({
  className,
  variant,
  shape,
  size,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(buttonVariants({ variant, shape, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }
